def apply(inputs, premises):
    answer = {}
    for i in range(len(inputs["asset_names"])):
        name = str(inputs["asset_names"][i])
        answer[name] = []
        if bool(inputs["qualifies_as_other_personal_property"][i]):
            if inputs["output_family"] == "EC":
                answer[name] = [premises["citation"]]
            if inputs["output_family"] == "EV":
                value = min(float(inputs["asset_values"][i]), float(premises["per_asset_claim_cap"]))
                answer[name] = [{"citation": premises["citation"], "claim_value": value}]
    return {"answer": answer}

