def apply(inputs, premises):
    record = inputs["record"]
    total = int(record["ticket_price"])
    personal_used = False
    carry_used = False
    checked_index = 0
    for i in range(len(record["bag_lengths"])):
        personal_ok = record["bag_lengths"][i] <= record["personal_item_limits"][0] and record["bag_widths"][i] <= record["personal_item_limits"][1] and record["bag_heights"][i] <= record["personal_item_limits"][2]
        carry_ok = record["bag_lengths"][i] <= record["carry_on_limits"][0] and record["bag_widths"][i] <= record["carry_on_limits"][1] and record["bag_heights"][i] <= record["carry_on_limits"][2]
        carried = False
        if personal_ok and not personal_used:
            personal_used = True
            carried = True
        if not carried and carry_ok and not carry_used:
            carry_used = True
            carried = True
        if not carried:
            base_fee = int(record["checked_base_fees"][checked_index])
            weight_limit = float(record["checked_weight_limits"][checked_index])
            weight = float(record["bag_weights"][i])
            overweight_fee = 0
            if weight > weight_limit and weight <= float(record["overweight_upper_bounds"][0]):
                overweight_fee = int(record["overweight_band_fees"][0])
            if weight > weight_limit and weight > float(record["overweight_upper_bounds"][0]) and weight <= float(record["overweight_upper_bounds"][1]):
                overweight_fee = int(record["overweight_band_fees"][1])
            if weight > weight_limit and weight > float(record["overweight_upper_bounds"][1]) and weight <= float(record["overweight_upper_bounds"][2]):
                overweight_fee = int(record["overweight_band_fees"][2])
            size = float(record["bag_lengths"][i]) + float(record["bag_widths"][i]) + float(record["bag_heights"][i])
            oversize_fee = 0
            if size > float(record["oversize_upper_bounds"][0]) and size <= float(record["oversize_upper_bounds"][1]):
                oversize_fee = int(record["oversize_band_fees"][0])
            if size > float(record["oversize_upper_bounds"][1]) and size <= float(record["oversize_upper_bounds"][2]):
                oversize_fee = int(record["oversize_band_fees"][1])
            excess_fee = overweight_fee + oversize_fee
            if premises["simultaneous_excess_rule"] == "higher_only":
                excess_fee = max(overweight_fee, oversize_fee)
            total = total + base_fee + excess_fee
            checked_index = checked_index + 1
    return {"answer": int(total)}

